-- schema.sql: Spring Boot runs this at startup on our in-memory H2 database, then runs data.sql.
-- A table is like a class: columns = fields, rows = objects.
-- GENERATED BY DEFAULT AS IDENTITY: the database picks each new id (1, 2, 3, ...).
-- "year" works only because of NON_KEYWORDS=YEAR in application.properties.

CREATE TABLE vehicles (
    id    INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    model VARCHAR(50),
    year  INT
);
